const rows = $input.all().map(i => i.json).filter(r => r && r['Setting Key']);

const toE164 = (raw) => {
  const digits = String(raw == null ? '' : raw).replace(/\D/g, '');
  if (!digits) return '';
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  if (digits.length === 10) return '+1' + digits;
  return '+' + digits;
};

const parseByType = (rawValue, dataType) => {
  const v = String(rawValue === undefined || rawValue === null ? '' : rawValue);
  switch ((dataType || '').trim().toLowerCase()) {
    case 'number': return Number(v);
    case 'boolean': return v.trim().toLowerCase() === 'true';
    case 'csv': return v.split(',').map(s => s.trim()).filter(Boolean);
    case 'phone': return toE164(v);
    default: return v;
  }
};

const fromSheet = {};
for (const row of rows) {
  const key = String(row['Setting Key']).trim();
  fromSheet[key] = parseByType(row['Value'], row['Data Type']);
}

const settings = { ...DEFAULTS, ...fromSheet };

const digitsOnly = String(settings.owner_phone_e164 || '').replace(/\D/g, '');
settings.owner_phone_digits = (digitsOnly.length === 11 && digitsOnly.startsWith('1')) ? digitsOnly.slice(1) : digitsOnly;

const dayNames = { 1: 'Monday', 2: 'Tuesday', 3: 'Wednesday', 4: 'Thursday', 5: 'Friday', 6: 'Saturday', 7: 'Sunday' };
const workingDays = Array.isArray(settings.working_days) ? settings.working_days.map(Number) : [];
const isConsecutiveMonFri = workingDays.length === 5 && workingDays.every((d, idx) => d === idx + 1);
const dayRangeLabel = isConsecutiveMonFri
  ? (dayNames[workingDays[0]] + '-' + dayNames[workingDays[workingDays.length - 1]])
  : workingDays.map(d => dayNames[d]).join(', ');

const fmtHour = (h) => {
  const hour = Number(h);
  const period = hour >= 12 ? 'PM' : 'AM';
  const display = hour % 12 === 0 ? 12 : hour % 12;
  return display + ':00 ' + period;
};

settings.business_hours_description = dayRangeLabel + ' ' + fmtHour(settings.business_start_hour) + '-' + fmtHour(settings.business_end_hour) +
  ' ' + settings.timezone.replace('America/New_York', 'Eastern Time').replace('_', ' ') +
  ', appointments are in ' + settings.appointment_slot_minutes + '-minute increments';

return [{ json: settings }];
